const req = $('Broadcast Webhook').first().json;
const key = $input.first().json || {};
const rid = 'req_' + $execution.id;
const fail = (status, code, message) => [{ json: { valid: false, status_code: status, response: { ok: false, request_id: rid, error: { code, message } } } }];
if (!key.api_key || key.active !== true || !['hr', 'hr_admin'].includes(key.client)) return fail(401, 'UNAUTHORIZED', 'Missing or invalid API key for this endpoint');
const body = (req.body && typeof req.body === 'object' && !Array.isArray(req.body)) ? req.body : {};
const errors = [];
const ALLOWED = ['target_team', 'message_prompt', 'requested_by'];
for (const k of Object.keys(body)) if (!ALLOWED.includes(k)) errors.push('unknown field: ' + k);
if (!/^[a-z_]{2,40}$/.test(String(body.target_team || ''))) errors.push('target_team must be 2-40 lowercase letters or underscores');
if (typeof body.message_prompt !== 'string' || body.message_prompt.trim().length < 10) errors.push('message_prompt must be at least 10 characters');
else if (body.message_prompt.length > 3000) errors.push('message_prompt exceeds 3000 characters');
if (!/^[A-Za-z0-9_-]{1,64}$/.test(String(body.requested_by || ''))) errors.push('requested_by is required (letters, digits, _ or -)');
if (errors.length) return fail(400, 'VALIDATION_ERROR', errors.join('; '));
return [{ json: { valid: true, request_id: rid, target_team: body.target_team, requested_by: body.requested_by, message_prompt: body.message_prompt } }];

const v = $('Authorize and Validate').first().json;
const t = $input.first().json || {};
if (!t.team_id) return [{ json: { valid: false, status_code: 422, response: { ok: false, request_id: v.request_id, error: { code: 'UNKNOWN_TEAM', message: 'target_team does not exist' } } } }];
return [{ json: { valid: true, request_id: v.request_id, requested_by: v.requested_by, raw_draft: v.message_prompt, team: { team_id: t.team_id, display_name: t.display_name, member_count: t.member_count, tone_guide: t.tone_guide }, fields: { message_prompt: v.message_prompt } } }];

const g = $input.first().json;
const v = $('Resolve Team').first().json;
const guard = $('Run sub-guard').first().json;
const rawDraft = v.raw_draft;
const cleanDraft = (guard.clean && guard.clean.message_prompt) || '';
const str = (x, n) => String(x ?? '').replace(/<[^>]*>/g, '').trim().slice(0, n);
const flags = (guard.flags || []).slice();
const o = (g && g.ok && g.out && typeof g.out === 'object') ? g.out : null;
let subject = '';
let body = '';
let key_points = [];
let missing_info = [];
let tone_notes = '';
if (o) {
  subject = str(o.subject, 70);
  body = str(o.body, 3000);
  key_points = Array.isArray(o.key_points) ? o.key_points.map(k => str(k, 200)).filter(Boolean).slice(0, 12) : [];
  missing_info = Array.isArray(o.missing_info) ? o.missing_info.map(k => str(k, 120)).filter(Boolean).slice(0, 8) : [];
  tone_notes = str(o.tone_notes, 300);
  if (o.injection_attempt_observed === true) flags.push({ field: 'message_prompt', type: 'model_observed_injection' });
} else {
  flags.push({ field: 'model', type: (g && g.error) || 'ai_unavailable' });
}
if (!subject) subject = 'Update for the ' + v.team.display_name + ' team';
if (!body) body = cleanDraft;
const text = subject + '\n' + body;
const numbers = Array.from(new Set(text.match(/\b\d[\d:./-]*\b/g) || []));
const unverified_figures = numbers.filter(n => !rawDraft.includes(n));
const links = text.match(/https?:\/\/[^\s)]+/g) || [];
const added_links = links.filter(u => !rawDraft.includes(u));
for (const u of added_links) { body = body.split(u).join('[link removed]'); subject = subject.split(u).join(''); }
const checks = { unverified_figures, added_links, passed: unverified_figures.length === 0 && added_links.length === 0 };
const approval_id = 'apr_' + $execution.id;
const draft = { subject, body };
const injection = flags.some(f => f.field !== 'model');
return [{ json: {
  approval_id,
  team_id: v.team.team_id,
  created_by: v.requested_by,
  payload_json: JSON.stringify({ draft, ai_draft: draft, key_points, missing_info, tone_notes, recipient_count: v.team.member_count }),
  checks_json: JSON.stringify({ checks, flags }),
  response: { ok: true, request_id: v.request_id, data: { approval_id, status: 'pending_approval', target_team: v.team.team_id, recipient_count: v.team.member_count, draft, key_points, missing_info, tone_notes, checks }, security: { injection_suspected: injection, flags } }
} }];
